function home(){return '<section class="hero"><div class="container hero-grid"><div><div class="eyebrow">مدیریت، خدمات و هوشمندسازی ساختمان</div><h1>ساختمان را بهتر اداره کنیم؛<br>خدمات را ساده‌تر دریافت کنیم</h1><p>برج پورتال راهکاری برای سامان‌دهی امور برج‌ها و مجتمع‌های مسکونی است؛ از مدیریت مالی و ارتباط با ساکنان تا رسیدگی به درخواست‌ها، نگهداری تجهیزات و هماهنگی خدمات روزانه. هر موضوع در مسیر مشخص خود ثبت می‌شود و امکان پیگیری آن برای افراد مسئول فراهم است.</p><div class="hero-actions"><a class="btn" href="services.html">مشاهده خدمات '+I.arrow+'</a><a class="btn btn-outline" href="about.html">آشنایی با مجموعه</a></div><div class="hero-points"><span>مدیریت منظم‌تر</span><span>ارتباط روشن‌تر</span><span>پیگیری دقیق‌تر</span></div></div><div class="hero-visual"><img src="assets/images/residential-courtyard.jpg" alt="فضای مشترک یک مجموعه مسکونی"><div class="visual-tag"><strong>از مدیریت تا خدمات روزمره</strong>یک مسیر روشن برای اداره بهتر ساختمان</div><div class="hero-stamp"><span>برج</span><b>پورتال</b><small>مدیریت و خدمات ساختمان</small></div></div></div></section><div class="stats-strip"><div class="container stats"><div class="stat"><strong>مدیریت ساختمان</strong><span>امور اجرایی، مالی و گزارش‌ها</span></div><div class="stat"><strong>خدمات ساکنان</strong><span>درخواست، پیگیری و اطلاع‌رسانی</span></div><div class="stat"><strong>نگهداری و تعمیرات</strong><span>تجهیزات، سرویس و پیمانکاران</span></div><div class="stat"><strong>هوشمندسازی</strong><span>پایش و کنترل تجهیزات منتخب</span></div></div></div><section class="section"><div class="container"><div class="section-head"><div><div class="kicker">خدمات برج پورتال</div><h2>برای هر بخش از زندگی ساختمان، راهکاری روشن</h2></div><p>خدمات در چند حوزه روشن دسته‌بندی شده‌اند تا مدیر ساختمان، کارکنان و ساکنان بدانند هر کار را از کجا آغاز و چگونه پیگیری کنند.</p></div><div class="cards">'+card('grid','مدیریت و امور مالی','ثبت اطلاعات ساختمان و واحدها، مدیریت هزینه‌ها و شارژ، بودجه، پرداخت‌ها، گزارش مالی و صورت‌جلسه‌ها.','services.html')+card('users','پورتال ساکنان و واحدها','دسترسی هر واحد به اطلاعیه‌ها، صورت‌حساب‌ها، ثبت درخواست، پیگیری خدمات و امکانات مشترک ساختمان.','services.html')+card('settings','تعمیرات و نگهداری','ثبت خرابی، ارجاع کار به نیروی فنی یا پیمانکار، برنامه سرویس دوره‌ای و نگهداری سوابق تجهیزات.','services.html')+card('building','خدمات اجرایی و پشتیبانی','سامان‌دهی امور نگهبانی، نظافت، تأسیسات، تردد، مهمانان، مرسولات و رسیدگی به رخدادها.','services.html')+card('services','امکانات و رفاه ساکنان','مدیریت رزرو فضاهای مشترک، درخواست خدمات رفاهی و اطلاع‌رسانی برنامه‌ها و رویدادهای ساختمان.','services.html')+card('tower','پایش و هوشمندسازی','اتصال تدریجی تجهیزات و حسگرهای منتخب برای پایش وضعیت، مصرف انرژی و رخدادهای فنی ساختمان.','services.html')+'</div></div></section><section class="section soft"><div class="container split"><div><div class="kicker">برای همه نقش‌های ساختمان</div><h2>هر فرد، ابزار متناسب با مسئولیت خود</h2><p style="color:var(--muted)">برج پورتال ارتباط میان مدیریت، کارکنان اجرایی، ساکنان و ارائه‌دهندگان خدمات را در یک چارچوب منظم برقرار می‌کند.</p><ul class="check-list"><li>پنل مدیریت برای اداره امور و مشاهده گزارش‌ها</li><li>پورتال ساکنان برای ارتباط با مدیریت و دریافت خدمات</li><li>محیط کاری برای نگهبانی، کارکنان و تیم‌های فنی</li><li>امکان تعریف صفحه و دسترسی اختصاصی برای هر واحد</li></ul><a class="btn" href="platform.html">آشنایی با نحوه کار سامانه</a></div><img src="assets/images/security-control-room.jpg" alt="محیط پایش و کنترل ساختمان"></div></section><section class="section"><div class="container"><div class="section-head"><div><div class="kicker">خدمات در سطح هر برج</div><h2>مدیریت هر ساختمان با اطلاعات و نیازهای خودش</h2></div><p>برای هر برج، فضای کاری و اطلاعات همان ساختمان تعریف می‌شود؛ در عین حال، امکان ارائه خدمات تخصصی و پشتیبانی مشترک برای چند ساختمان نیز وجود دارد.</p></div><div class="banner"><div><h2>می‌خواهید خدمات برج پورتال را برای ساختمان خود بررسی کنید؟</h2><p>با ما در ارتباط باشید تا نیازهای ساختمان و حوزه‌های قابل استفاده را مرور کنیم.</p></div><a class="btn" href="contact.html">درخواست مشاوره '+I.arrow+'</a></div></div></section><section class="section home-process"><div class="container"><div class="section-head"><div><div class="kicker">مسیر انجام کار</div><h2>از ثبت درخواست تا ثبت نتیجه</h2></div><p>هر موضوع در یک فرآیند روشن پیش می‌رود؛ مسئول رسیدگی مشخص می‌شود و سابقه اقدام‌ها برای پیگیری بعدی باقی می‌ماند.</p></div><div class="process-grid"><article><b>۰۱</b><h3>ثبت موضوع</h3><p>درخواست، خرابی یا نیاز اجرایی ثبت می‌شود.</p></article><article><b>۰۲</b><h3>بررسی و ارجاع</h3><p>موضوع به مسئول یا واحد مرتبط ارجاع داده می‌شود.</p></article><article><b>۰۳</b><h3>اقدام و پیگیری</h3><p>وضعیت رسیدگی و مراحل انجام کار مشخص است.</p></article><article><b>۰۴</b><h3>ثبت نتیجه</h3><p>نتیجه و سوابق در پرونده مربوط نگهداری می‌شود.</p></article></div></div></section><section class="section soft home-roles"><div class="container"><div class="section-head"><div><div class="kicker">مخاطبان خدمات</div><h2>برای مدیران، ساکنان و تیم‌های اجرایی</h2></div><p>هر گروه، متناسب با نقش و مسئولیت خود به امکانات و اطلاعات موردنیاز دسترسی پیدا می‌کند.</p></div><div class="feature-grid"><article class="feature"><div class="iconbox">'+I.building+'</div><div><h3>مدیران و هیئت‌مدیره</h3><p>برای نظارت بر امور، بررسی گزارش‌ها، مدیریت هزینه‌ها و تصمیم‌گیری درباره خدمات.</p></div></article><article class="feature"><div class="iconbox">'+I.users+'</div><div><h3>مالکان و ساکنان</h3><p>برای دریافت اطلاعیه، مشاهده اطلاعات واحد، ثبت درخواست و پیگیری امور.</p></div></article><article class="feature"><div class="iconbox">'+I.settings+'</div><div><h3>کارکنان و پیمانکاران</h3><p>برای دریافت وظایف، ثبت گزارش و نگهداری سوابق فعالیت‌های اجرایی و فنی.</p></div></article><article class="feature"><div class="iconbox">'+I.services+'</div><div><h3>ارائه‌دهندگان خدمات</h3><p>برای هماهنگی فعالیت‌ها و پاسخ‌گویی منظم به نیازهای ساختمان.</p></div></article></div></div></section><section class="section photo-section"><div class="container"><div class="section-head"><div><div class="kicker">محیط‌های ساختمانی</div><h2>حوزه‌های مختلف مدیریت ساختمان</h2></div><p>فضاهای نمونه‌ای که نگهداری، خدمات و مدیریت آن‌ها در پلتفرم قابل سامان‌دهی است.</p></div><div class="photo-gallery"><figure class="photo-card photo-wide"><img src="assets/images/residential-exterior.jpg" alt="نمای بیرونی ساختمان مسکونی"><figcaption>نمای ساختمان</figcaption></figure><figure class="photo-card"><img src="assets/images/elevator-lobby.jpg" alt="آسانسور و فضای ورودی ساختمان"><figcaption>آسانسور و ورودی</figcaption></figure><figure class="photo-card"><img src="assets/images/rooftop-pool.jpg" alt="استخر و تراس بام"><figcaption>امکانات رفاهی</figcaption></figure><figure class="photo-card"><img src="assets/images/garden-walkway.jpg" alt="مسیر پیاده‌روی در فضای سبز"><figcaption>فضای سبز</figcaption></figure><figure class="photo-card"><img src="assets/images/residential-gym.jpg" alt="باشگاه ورزشی ساختمان"><figcaption>باشگاه ورزشی</figcaption></figure><figure class="photo-card"><img src="assets/images/residential-facade-detail.jpg" alt="جزئیات نمای معماری ساختمان"><figcaption>جزئیات معماری</figcaption></figure></div></div></section><section class="section home-product-callout"><div class="container"><div class="banner"><div><div class="kicker">محصولات و بسته‌های فروش</div><h2>راهکار مناسب ساختمان خود را انتخاب کنید</h2><p>محصولات نرم‌افزاری، خدمات تخصصی و تجهیزات هوشمند را مستقل یا در قالب بسته یکپارچه دریافت کنید.</p></div><a class="btn" href="products.html">ورود به کاتالوگ محصولات '+I.arrow+'</a></div></div></section>'}
function about(){return hero(pages.about.title,pages.about.desc,pages.about.crumb)+'<main class="page-body"><div class="container"><section class="about-lead split"><div><div class="kicker">معرفی مجموعه</div><h2>برج پورتال؛ پیوند مدیریت، خدمات و فناوری در ساختمان</h2><p style="color:var(--muted);line-height:2.2">برج پورتال با هدف بهبود شیوه اداره و بهره‌برداری از برج‌ها و مجتمع‌های مسکونی شکل گرفته است. در یک ساختمان، امور مالی، درخواست‌های ساکنان، نگهداری تأسیسات، خدمات اجرایی و اطلاع‌رسانی به یکدیگر وابسته‌اند؛ اما در بسیاری از مواقع این امور در مسیرهای جداگانه و بدون سابقه روشن انجام می‌شوند.</p><p style="color:var(--muted);line-height:2.2">رویکرد برج پورتال، سامان‌دادن این فرآیندها در یک بستر منظم است؛ بستری که اطلاعات ساختمان را ساخت‌یافته نگهداری کند، ارتباط میان افراد را ساده‌تر سازد و پیگیری کارها را از ثبت درخواست تا ثبت نتیجه امکان‌پذیر کند. فناوری در این مجموعه هدف مستقل نیست؛ ابزاری است برای پاسخ‌گویی بهتر، کاهش پراکندگی اطلاعات و ارتقای کیفیت مدیریت و خدمات ساختمان.</p></div><img src="assets/images/residential-exterior.jpg" alt="ساختمان مسکونی و فضاهای مشترک"></section><section class="section"><div class="section-head"><div><div class="kicker">حوزه فعالیت</div><h2>چه خدماتی ارائه می‌کنیم؟</h2></div><p>خدمات برج پورتال در چند حوزه مکمل تعریف شده‌اند و متناسب با شرایط و نیاز هر ساختمان قابل برنامه‌ریزی هستند.</p></div><div class="cards">'+card('grid','سامان‌دهی مدیریت ساختمان','اطلاعات برج و واحدها، امور مالی، بودجه، مصوبات، جلسات، گزارش‌ها و پیگیری عملکرد.')+card('users','خدمات و ارتباط با ساکنان','پورتال اختصاصی واحد، اطلاعیه‌ها، درخواست‌ها، پیگیری، رزرو امکانات و ارتباط با مدیریت.')+card('settings','نگهداری و پشتیبانی فنی','پرونده تجهیزات، برنامه سرویس، ثبت خرابی، دستورکار تعمیرات و هماهنگی پیمانکاران.')+card('building','خدمات اجرایی و رفاهی','نظافت، نگهبانی، تأسیسات، مهمان و مرسولات، خدمات رفاهی و مدیریت فضاهای مشترک.')+card('tower','هوشمندسازی و پایش','اتصال تجهیزات و حسگرهای منتخب، پایش وضعیت و مصرف و توسعه قابلیت‌های هوشمند.')+card('services','راه‌اندازی و پشتیبانی سامانه','شناخت نیاز ساختمان، تعریف ساختار و کاربران، آماده‌سازی خدمات و همراهی در توسعه و بهبود.')+'</div></section><section class="section soft"><div class="section-head"><div><div class="kicker">شیوه ارائه خدمات</div><h2>خدمات چگونه در اختیار ساختمان قرار می‌گیرد؟</h2></div><p>ساختار کار به‌گونه‌ای است که هر گروه، ابزار و مسیر مشخصی برای انجام وظایف و دریافت خدمات داشته باشد.</p></div><div class="feature-grid">'+feature('building','فضای اختصاصی هر برج','اطلاعات، واحدها، کاربران، امور مالی و فرآیندهای هر ساختمان در محیط مخصوص همان برج مدیریت می‌شود.')+feature('users','دسترسی اختصاصی هر واحد','ساکنان می‌توانند از صفحه واحد خود، اطلاعیه‌ها و صورت‌حساب‌ها را ببینند و درخواست خدمات ثبت و پیگیری کنند.')+feature('settings','مراکز تخصصی خدمات','امور فنی، تعمیرات، نظافت، نگهبانی و سایر خدمات می‌توانند از مسیرهای تخصصی و هماهنگ به برج‌ها ارائه شوند.')+feature('grid','مدیریت و گزارش‌گیری یکپارچه','مدیران مجاز می‌توانند وضعیت درخواست‌ها، هزینه‌ها، عملیات و عملکرد خدمات را در گزارش‌های منظم بررسی کنند.')+'</div></section><section class="section"><div class="section-head"><div><div class="kicker">رویکرد ما</div><h2>فناوری در خدمت کیفیت زندگی و بهره‌برداری</h2></div></div><ul class="check-list"><li>شفاف‌کردن مسئولیت‌ها و قابل پیگیری‌کردن درخواست‌ها</li><li>کاهش پراکندگی اطلاعات و دوباره‌کاری در امور روزمره</li><li>ثبت سوابق مالی، فنی و اجرایی برای تصمیم‌گیری بهتر</li><li>توجه هم‌زمان به نیاز مدیران، کارکنان، مالکان و ساکنان</li><li>توسعه خدمات به‌صورت مرحله‌ای و متناسب با نیاز هر ساختمان</li></ul><div class="banner"><div><h2>برای شناخت خدمات متناسب با ساختمان خود گفت‌وگو کنیم</h2><p>شرح کوتاهی از ساختمان و نیازهای خود را برای ما ارسال کنید.</p></div><a class="btn" href="contact.html">ارتباط با مجموعه '+I.arrow+'</a></div></section><section class="section soft about-purpose"><div class="section-head"><div><div class="kicker">مأموریت مجموعه</div><h2>ساختمان، مجموعه‌ای از خدمات به‌هم‌پیوسته</h2></div><p>هدف ما ایجاد ارتباط روشن میان تصمیم‌گیری مدیریتی، عملیات روزانه، نیاز ساکنان و نگهداری دارایی‌های ساختمان است.</p></div><div class="mission-grid"><article><b>مدیریت شفاف</b><p>اطلاعات، هزینه‌ها، مصوبات و گزارش‌ها در مسیرهای مشخص و قابل بررسی قرار می‌گیرند.</p></article><article><b>خدمات پاسخ‌گو</b><p>درخواست‌ها به مسئول مرتبط می‌رسند و وضعیت رسیدگی و نتیجه آن‌ها ثبت می‌شود.</p></article><article><b>نگهداری برنامه‌ریزی‌شده</b><p>تجهیزات و تأسیسات با پرونده و سوابق سرویس و تعمیرات مدیریت می‌شوند.</p></article></div></section><section class="section about-method"><div class="section-head"><div><div class="kicker">نحوه همکاری</div><h2>از شناخت ساختمان تا توسعه خدمات</h2></div><p>خدمات با شناخت شرایط واقعی هر مجموعه آغاز می‌شوند و متناسب با اولویت‌ها و ظرفیت ساختمان توسعه پیدا می‌کنند.</p></div><div class="process-grid"><article><b>۰۱</b><h3>شناخت نیازها</h3><p>بررسی ساختار مدیریت، واحدها، خدمات فعلی و مسائل اولویت‌دار.</p></article><article><b>۰۲</b><h3>تعریف ساختار</h3><p>تنظیم اطلاعات برج، نقش‌ها، دسترسی‌ها و فرآیندهای موردنیاز.</p></article><article><b>۰۳</b><h3>راه‌اندازی</h3><p>آماده‌سازی محیط کار و همراهی برای آغاز استفاده از خدمات.</p></article><article><b>۰۴</b><h3>توسعه و بهبود</h3><p>تکمیل امکانات بر اساس بازخوردها و نیازهای جدید ساختمان.</p></article></div></section></div></main>'}

function platform(){return hero(pages.platform.title,pages.platform.desc,pages.platform.crumb)+'<main class="page-body"><div class="container"><div class="split"><div><div class="kicker">ساختار محصول</div><h2>مرکزیت در راهبری؛ استقلال در اجرا</h2><p style="color:var(--muted)">هر برج به‌عنوان یک فضای داده مستقل تعریف می‌شود. مدیر پلتفرم می‌تواند وضعیت کلی شبکه را ببیند، اما دسترسی به داده‌های هر ساختمان بر اساس مجوز و نقش کنترل می‌شود.</p><ul class="check-list"><li>تفکیک سازمان، برج، بلوک، طبقه، واحد و فضاهای مشترک</li><li>تعریف نقش و سطح دسترسی برای هر گروه کاربری</li><li>مدیریت متمرکز تنظیمات مشترک و خدمات پایه</li><li>گزارش تجمیعی بدون افشای اطلاعات بین برج‌ها</li><li>استقرار ابری، اختصاصی یا ترکیبی بر اساس نیاز</li></ul></div><img src="assets/images/residential-lobby.jpg" alt="تصویر لابی مدرن یک ساختمان مسکونی"></div><div class="section-head" style="margin-top:55px"><div><div class="kicker">خانواده محصولات</div><h2>چهار محیط هماهنگ</h2></div></div><div class="product-row"><div class="product"><b>Tower Admin</b><span>مدیریت، مالی، راهبری و گزارش‌ها</span></div><div class="product"><b>Tower Resident</b><span>خدمات، درخواست‌ها و ارتباط ساکنان</span></div><div class="product"><b>Tower Ops</b><span>عملیات روزانه، نگهبانی و تیم فنی</span></div><div class="product"><b>Tower IoT</b><span>درگاه تجهیزات، حسگرها و پایش</span></div></div></div></main>'}
